def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    def grundy(n, k):
        if n == 0:
            return 0
        if n == 1:
            return 1
        if n % 2 == 1:  # odd
            return grundy(n - 1, k) ^ 1
        else:  # even
            if k % 2 == 0:  # even k - split gives XOR 0
                return grundy(n - 1, k)
            else:  # odd k - split gives XOR of Grundy(n/2)
                return grundy(n - 1, k) ^ grundy(n // 2, k)

    # Memoization for efficiency
    memo = {}

    def grundy_fast(n):
        if n in memo:
            return memo[n]
        if n == 0:
            return memo[n] = 0
        if n == 1:
            return memo[n] = 1
        if n % 2 == 1:  # odd
            val = grundy_fast(n - 1) ^ 1
            return memo[n] = val
        else:  # even
            if k % 2 == 0:
                val = grundy_fast(n - 1)
            else:
                val = grundy_fast(n - 1) ^ grundy_fast(n // 2)
            return memo[n] = val

    xor_sum = 0
    for pile in a:
        xor_sum ^= grundy_fast(pile)

    result = "Kevin" if xor_sum != 0 else "Nicky"
    return result + "\n"


