from collections import defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "NO"

    n, m = map(int, lines[0].split())

    clauses = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        literals = parts[1:]
        clauses.append(literals)

    # Track how many times each variable appears (in clauses we still need)
    var_count = [0] * (m + 1)
    for clause in clauses:
        for lit in clause:
            var_count[abs(lit)] += 1

    # Build implication graph: for clause [l1, l2, ..., lk], we need at least one true
    # For 2-SAT, clause (A or B) means ~A -> B and ~B -> A
    # For clauses with k >= 3 literals, we can use a chain implication approach

    adj = defaultdict(list)

    def add_implication(from_lit, to_lit):
        # ~from_lit -> to_lit
        # Literal x: true node is 2*(x-1), false node is 2*(x-1)+1
        # Literal ~x: true node is 2*(x-1)+1, false node is 2*(x-1)

        def get_node(l, true_val):
            """Get node for literal l being true_val (True/False)"""
            var = abs(l) - 1
            if l > 0:  # positive literal
                return true_val * 2
            else:  # negative literal
                return (1 if true_val else 0) * 2 + 1

        from_false = get_node(from_lit, False)
        to_true = get_node(to_lit, True)
        adj[from_false].append(to_true)

    # For each clause, add implications
    for clause in clauses:
        if len(clause) == 1:
            # Unit clause: must be satisfied
            add_implication(clause[0], clause[0])  # tautology that gets us a forced assignment
        elif len(clause) == 2:
