            if s[i-1] == 0:
                return False
            # Use cross-multiplication: s[i]/s[i-1] == num/den
            if s[i] * den != s[i-1] * num:
                return False

        return True

    def can_be_gp(seq):
        n = len(seq)
        for i in range(n):
            filtered = seq[:i] + seq[i+1:]
            if is_gp(filtered):
                return True
        return False

    if is_gp(seq):
        return "0\n"
    elif can_be_gp(seq):
        return "1\n"
    else:
        return "2\n"

