    lines = input_data.strip().split('\n')
    n, k, x = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    result = a[:]

    # For each non-zero element, calculate the cost (operations) to reach zero
    costs = []
    for i in range(n):
        if a[i] != 0:
            cost = (abs(a[i]) + x - 1) // x  # Ceiling division
            costs.append((cost, i))

    # Sort elements by cost to zero (cheapest first)
    costs.sort()

    remaining = k
    for cost, i in costs:
        if remaining <= 0:
            break
        if remaining >= cost:
            # We can make this element exactly zero
            result[i] = 0
            remaining -= cost
        else:
            # Use all remaining operations on this element
            # Move it as close to zero as possible in the direction toward zero
            if a[i] > 0:
                result[i] -= remaining * x
            else:
                result[i] += remaining * x
            remaining = 0

    return ' '.join(map(str, result))

