            for j in range(1, n + 1):
                if s1[i-1] == s2[j-1]:
                    dp[i][j] = dp[i-1][j-1] + 1
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i][j-1])

        if dp[m][n] == 0:
            return "0"

        # Reconstruct
        result = []
        i, j = m, n
        while i > 0 and j > 0:
            if s1[i-1] == s2[j-1] and dp[i][j] == dp[i-1][j-1] + 1:
                result.append(s1[i-1])
                i -= 1
                j -= 1
            elif dp[i-1][j] >= dp[i][j-1]:
                i -= 1
            else:
                j -= 1

        return ''.join(reversed(result))

