    # k = length of longest suffix of virus that matches a suffix of our common subsequence
    dp = [[[""] * vm for _ in range(n + 1)] for _ in range(m + 1)]
    lengths = [[[-1] * vm for _ in range(n + 1)] for _ in range(m + 1)]

    # Initialize base cases
    for i in range(m + 1):
        for j in range(n + 1):
            for k in range(vm):
                lengths[i][j][k] = 0
                dp[i][j][k] = ""

    # Fill DP table
