            for k in range(vm):
                # Option 1: Skip s1[i-1]
                best_len = lengths[i-1][j][k]
                best_seq = dp[i-1][j][k]

                # Option 2: Skip s2[j-1]
                if lengths[i][j-1][k] > best_len or (lengths[i][j-1][k] == best_len and len(dp[i][j-1][k]) >= len(best_seq)):
                    best_len = lengths[i][j-1][k]
                    best_seq = dp[i][j-1][k]

                # Option 3: Match if s1[i-1] == s2[j-1]
                if s1[i-1] == s2[j-1]:
                    char = s1[i-1]

                    # Calculate new mask after including this character
                    new_k = 0
                    temp_k = k

                    # Try to compute the new state after appending char
                    temp_k = k
                    # Check if adding char would complete virus
                    if temp_k == vm - 1 and char == virus[-1]:
                        # If we'd complete virus, we can't use this match
                        continue

                    # Calculate what the new prefix match would be
                    temp_k = 0
                    for idx in range(vm):
                        if idx == k and char == virus[idx]:
                            temp_k += 1
                            break
                        elif idx > k and char == virus[idx - 1]:
                            break

                    new_k = temp_k

                    # Recursively get the prefix
                    prev_len = lengths[i-1][j-1][k]
                    prev_seq = dp[i-1][j-1][k]

                    if new_k < vm and len(prev_seq) < best_len:
                        candidate_len = prev_len + 1
                        candidate_seq = prev_seq + char
                        if candidate_len > best_len or (candidate_len == best_len and len(candidate_seq) >= len(best_seq)):
                            best_len = candidate_len
                            best_seq = candidate_seq

                lengths[i][j][k] = best_len
                dp[i][j][k] = best_seq

    # Find the best result across all final states
    best_len = 0
    best_seq = ""

    for k in range(vm):
