        adj[u].append(v)
        adj[v].append(u)

    def build_flow_network(n, start, end):
        """Build flow network for finding internally vertex-disjoint paths."""
        # Total nodes: 2*n + 2 (n_in + n_out for each vertex + source + sink)
        # v_in = 2*v, v_out = 2*v + 1
        num_nodes = 2 * n + 2
        source = 2 * start
        sink = 2 * end + 1

        graph = [[] for _ in range(num_nodes)]
        residual = [[0] * num_nodes for _ in range(num_nodes)]

        def add_edge(u, v, capacity):
            graph[u].append([v, capacity, len(graph[v])])
            graph[v].append([u, 0, len(graph[u]) - 1])
            residual[u][v] = capacity

        # Split each vertex: v_in -> v_out with vertex capacity
        for v in range(1, n + 1):
            in_node = 2 * v
            out_node = 2 * v + 1
            # Vertex capacity: can pass up to 3 paths through
            if v == start or v == end:
                v_cap = 3 * n  # High capacity for start/end
            else:
                v_cap = 3  # Max 3 paths through any intermediate vertex
            add_edge(in_node, out_node, v_cap)

        # Add graph edges: u_out -> v_in with capacity 1 for each (u,v)
        for v in range(1, n + 1):
            for neighbor in adj[v]:
                # Add directed edges for both (v,neighbor) and (neighbor,v)
                v_in, v_out = 2 * v, 2 * v + 1
                neighbor_in, neighbor_out = 2 * neighbor, 2 * neighbor + 1

                # Only add if not duplicate (each undirected edge becomes 2 directed)
                if neighbor > v:  # Prevent duplicate undirected edges
                    continue

                # Add both directions (since undirected graph)
                add_edge(v_out, neighbor_in, 1)

        return graph, start, sink

    def bfs_flow(graph, num_nodes, s, t):
        """BFS-based max flow Edmonds-Karp."""
        flow = 0
        while True:
            dist = [-1] * num_nodes
            parent = [-1] * num_nodes
            dist[s] = 0

            queue = [s]
            found = False

            while queue:
                u = queue.pop(0)
                if u == t:
                    found = True
                    break

                for v, cap, rev in graph[u]:
                    if cap > 0 and dist[v] == -1 and dist[v] < dist[u] + 1:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        if (<class 'list'>)(v, cap, rev) in graph[u]:
                            queue.append(v)

            if not found:
                break

            # Find bottleneck capacity
            bottleneck = float('inf')
            curr = t
            while curr != s:
                prev = parent[curr]
                # Find edge
                for v, cap, rev in graph[prev]:
                    if v == curr:
                        bottleneck = min(bottleneck, cap)
                        break
                curr = prev

            if bottleneck == 0:
                break

            # Augment flow
            flow += bottleneck
            curr = t
            while curr != s:
                prev = parent[curr]
                for u, cap, rev in graph[prev]:
                    if u == curr:
                        graph[prev][rev][1] -= bottleneck
                        break
                for v, cap, rev in graph[curr]:
