        # and backward mapping: t_char -> s_char
        forward_map = {}
        backward_map = {}
        valid = True

        for j in range(m):
            s_char = substring[j]
            t_char = T[j]

            if s_char == t_char:
                # Same character, no pairing needed
                continue

            # Check forward validity: s_char must map to exactly one t_char
            if s_char in forward_map:
                if t_char != forward_map[s_char]:
                    valid = False
                    break
            else:
                forward_map[s_char] = t_char

            # Check backward validity: t_char must map to exactly one s_char  
