from functools import lru_cache

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, h, m = map(int, lines[0].split())
    restrictions = []
    for i in range(m):
        l, r, x, c = map(int, lines[1 + i].split())
        restrictions.append((l, r, x, c))

    # The constraints are small enough for DP with memoization
    # State: tuple of (position, heights)
    # For efficiency, we'll track a reduced state

    @lru_cache(maxsize=None)
    def dp(idx, *prev_heights):
        ns = list(prev_heights)
        if idx == n:
            gain = sum(h * h for h in ns)
            fine = 0
            for l, r, x, c in restrictions:
                if ns[l-1:r]:
                    if max(ns[l-1:r]) > x:
                        fine += c
            return gain - fine

        best = -float('inf')
        for h in range(h + 1):
            ns = prev_heights + (h,)
            best = max(best, h * h + dp(idx + 1, *ns))
        return best

    result = dp(0, *())
    # Remove LRU cache from previous attempts
    del dp

    return str(result.value if hasattr(result, 'value') else result)

def solution(query_str):
    lines = query_str.strip().split('\n')
    if not lines:
        return '0\n'

    first_line = lines[0].split()
    if len(first_line) < 4:
        return '0\n'
    n, m, k, p = int(first_line[0]), int(first_line[1]), int(first_line[2]), int(first_line[3])

    bamboos = []
    for i in range(1, n + 1):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) >= 2:
            hi, ai = int(parts[0]), int(parts[1])
            bamboos.append((hi, ai))

    def can_achieve(target):
        hits_needed = 0
        for hi, ai in bamboos:
            if hi + m * ai > target:
                hits_needed += (hi + m * ai - target + p - 1) // p
        return hits_needed <= k * m

    if not bamboos:
        return '0\n'

    low = 0
    high = max(hi + m * ai for hi, ai in bamboos)
    result = high

    while low <= high:
        mid = (low + high) // 2
        if can_achieve(mid):
            result = mid
            high = mid - 1
        else:
            low = mid + 1

    return str(result) + '\n'

