def is_square_free(n):
    """Compute square-free part of n"""
    if n <= 1:
        return n
    result = 1
    d = 2
    while d * d <= n:
        if n % (d * d) == 0:
            while n % (d * d) == 0:
                n = n // (d * d)
        d += 1
    result = result * n
    return result

import random

def solution(input_str):
    n, r = map(int, input_str.split())

    # Generate all valid integer coordinate points within radius r
    candidates = []
    for x in range(-r, r+1):
        for y in range(-r, r+1):
            if x*x + y*y <= r*r:
                candidates.append((x, y))

    # Sort by squared distance from origin (descending) for greedy selection
    candidates.sort(key=lambda p: p[0]**2 + p[1]**2, reverse=True)

    best_score = -1
    best_config = None

    def compute_score(config):
        total_sq = sum(x*x + y*y for x, y in config)
        sum_x = sum(p[0] for p in config)
        sum_y = sum(p[1] for p in config)
        return n * total_sq - (sum_x*sum_x + sum_y*sum_y)

    # Multiple randomized searches
    for _ in range(5000):
        # Random initialization from candidates
        if len(candidates) >= n:
            idxs = random.sample(range(len(candidates)), n)
            config = [candidates[i] for i in idxs]
        else:
            config = [candidates[i % len(candidates)] for i in range(n)]

        current_score = compute_score(config)
        if current_score > best_score:
            best_score = current_score
            best_config = list(config)

        # Local optimization: try swapping positions
        for iteration in range(50):
            improved = False
            for i in range(n):
                for j in range(n):
                    test = list(config)
                    test[i], test[j] = test[j], test[i]
                    test_score = compute_score(test)
                    if test_score > best_score:
                        best_score = test_score
                        best_config = test
                        config = test
                        improved = True
                        break
                if improved:
                    break

    # Generate output
    output = [f"{best_score}"]
    for x, y in best_config:
        output.append(f"{x} {y}")

    return "\n".join(output) + "\n"

